-- Menu routing (D95; adjustments M2; T79): which menu an area or a table shows, one row per area
-- or table; the venue's live menu is the default. Generated by drizzle-kit, then edited by hand:
-- the menu's foreign key clears only `menu_id` when that menu is purged (ON DELETE SET NULL with
-- a column list: a plain SET NULL on a composite key would null `tenant_id` and `venue_id` too;
-- the Drizzle schema states the plain form, which is what drizzle-kit compares against), and
-- row-level security and the updated_at trigger are appended. Privileges come from
-- src/table-access.ts. No data: the dictionary starts empty (every code shows the live menu).
CREATE TABLE "restro"."menu_routes" (
	"tenant_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"area_id" text,
	"table_id" text,
	"menu_id" text,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "menu_routes_one_target" CHECK (("restro"."menu_routes"."area_id" is null) <> ("restro"."menu_routes"."table_id" is null))
);
