ALTER TABLE "restro"."menu_routes" ADD CONSTRAINT "menu_routes_table_fk" FOREIGN KEY ("tenant_id","table_id") REFERENCES "restro"."tables"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
